+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every "consume" movement, and the
+ * difference (actual minus theoretical). Items with no use are left out.
+ */
+export function varianceReport(store, from, to) {
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const use = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    const line = use.get(itemId) ?? { theoretical: 0, actual: 0 };
+    line.actual += m.qty;
+    if (m.ref.startsWith(SALE_REF)) line.theoretical += m.qty;
+    use.set(itemId, line);
+  }
+  const round = (n) => Math.round(n * 1000) / 1000;
+  return listItems(store)
+    .filter((item) => use.has(item.id))
+    .map((item) => {
+      const { theoretical, actual } = use.get(item.id);
+      return {
+        itemId: item.id,
+        name: item.name,
+        unit: item.unit,
+        theoretical: round(theoretical),
+        actual: round(actual),
+        difference: round(actual - theoretical),
+      };
+    });
+}
