+// Till sales: each dish sold uses one portion of its recipe per qty. The
+// ledger is the record of a sale: its "consume" movements carry the ref
+// sale:<ticket> and the time it was sold (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { onHand } from "./items.js";
+import { scaled } from "./recipes.js";
+
+/** The start of the ledger ref of every sale. */
+export const SALE_REF = "sale:";
+
+/**
+ * Books sale lines { row, ticket, soldAt, dishId, qty }, skipping tickets
+ * already imported. Everything is checked first, so a bad line changes
+ * nothing. Returns { tickets, dishes } counts for what was booked.
+ */
+export function recordSales(store, lines) {
+  const imported = new Set(store.data.movements.filter((m) => m.type === "consume").map((m) => m.ref));
+  const stock = new Map();
+  const planned = [];
+  for (const line of lines) {
+    const where = `row ${line.row}`;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === line.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const recipe = store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: the dish has no recipe` });
+    const ref = `${SALE_REF}${line.ticket}`;
+    if (imported.has(ref)) continue;
+    // Scaling can round a tiny ingredient down to nothing; there is nothing to take then.
+    const needs = scaled(recipe, line.qty).filter((n) => n.qty > 0);
+    for (const n of needs) {
+      const item = store.data.items.find((i) => i.id === n.itemId);
+      if (!item) throw new AppError("bad_request", { reason: `${where}: unknown item ${n.itemId}` });
+      const available = stock.get(n.itemId) ?? onHand(store, n.itemId);
+      if (available < n.qty)
+        throw new AppError("not_enough_stock", { item: `${item.name} (${where})`, available, unit: item.unit });
+      stock.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+    planned.push({ ref, ticket: line.ticket, soldAt: line.soldAt, qty: line.qty, needs });
+  }
+  for (const p of planned)
+    for (const n of p.needs) consume(store, n.itemId, n.qty, { at: p.soldAt, ref: p.ref });
+  return {
+    tickets: new Set(planned.map((p) => p.ticket)).size,
+    dishes: planned.reduce((sum, p) => sum + p.qty, 0),
+  };
+}
