@@ -0,0 +1,26 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty). The whole file is
+// checked first; one bad row and nothing is imported.
+import { AppError } from "../errors.js";
+import { isInstant } from "../dates.js";
+import { recordSales } from "../domain/sales.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const WHOLE = /^\d+$/;
+
+/** Imports sales; returns { tickets, dishes } counts or throws an AppError naming the row. */
+export function importSales(store, text) {
+  const lines = parseCsvObjects(text).map((r, i) => {
+    const row = i + 2;
+    const where = `row ${row}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+    const dishId = Number(r.dishId);
+    const qty = Number(r.qty);
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    if (!WHOLE.test(r.dishId) || !Number.isSafeInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    if (!WHOLE.test(r.qty) || !Number.isSafeInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { row, ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId, qty };
+  });
+  return recordSales(store, lines);
+}
